INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(10283, 'plPL', 'Dywersja Tarethy', 'Taretha odegrała kluczową rolę w przetrwaniu i wychowaniu Thralla i w ogromnym stopniu ukształtowała jego życie.$B$BTo Taretha wywołała pierwotną dywersję w Durnholdzie, dzięki której Thrall zdołał uciec.$B$BTeraz jednak Nieskończeni pojmali Tarethę i więżą ją w Smolnym Młynie. Bez naszego udziału dywersja się nie wydarzy. Musisz użyć ładunków zapalających, które ci dam, i spalić baraki internowania w Durnholdzie. Gdy to zrobisz, porozmawiaj z młodym Thrallem w więzieniu w piwnicach Durnholdu.', 'Udaj się do Twierdzy Durnhold i za pomocą paczki bomb zapalających od Eroziona podłóż 5 ładunków zapalających przy beczkach w każdym z baraków internowania.$B$BGdy baraki internowania staną w ogniu, porozmawiaj z Thrallem w więzieniu w piwnicach Twierdzy Durnhold.', '', 'Wróć do Thralla.', 'Podpalone baraki internowania', '', '', '', 0),
(10284, 'plPL', 'Ucieczka z Durnholdu', 'Patrzysz na mnie i widzisz tylko chłopca, ale w sercu i duszy skrywam swoje marzenia. Mam plany dla mojego ludu, nieznajomy. Pewnego dnia obalą swoich ciemiężców i powstaną jak jeden mąż. Zrzucą krępujące ich więzy, a z tego powstania narodzi się orkowa Horda.$B$BObiecuję ci, nieznajomy: jeśli wyjdziemy stąd żywi, a ja będę miał czym wynagrodzić ten bezinteresowny czyn, odszukam cię... Znajdę cię.$B$B<Thrall kiwa głową.>$B$BRuszymy, gdy będziesz $ggotów:gotowa;.', 'Gdy będziesz $ggotów:gotowa; ruszać, daj znać Thrallowi. Idź za Thrallem z Twierdzy Durnhold i pomóż mu uwolnić Tarethę oraz wypełnić jego przeznaczenie.$B$BGdy wykonasz to zadanie, porozmawiaj z Erozionem w Starym Międzygórzu.', '', 'Wróć do Eroziona w Starym Międzygórzu.', 'Przeznaczenie Thralla wypełnione', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(10283, 'plPL', 'Jesteście przyjaciółmi Tarethy? Więc to jej nowy plan? Dobrze zatem...', 0),
(10284, 'plPL', '$GDokonałeś:Dokonałaś; wielkiej rzeczy, $N. Niestety, młody wódz musi zapamiętać te wydarzenia tak, jak przebiegły pierwotnie... Andormu czeka na ciebie w leżu mistrza.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(10284, 'plPL', '<Erozion kiwa głową.>', 0);
