INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(9147, 'plPL', '%s ziewa.', '', 0),
(14467, 'plPL', 'Kim jesteś? Po prostu zostaw mnie w spokoju.', '', 0),
(14468, 'plPL', 'Jesteśmy gotowi cię stąd wyciągnąć, Thrallu. Ruszajmy!', 'Jesteśmy gotowi cię stąd wyciągnąć, Thrallu. Ruszajmy!', 0),
(15114, 'plPL', 'Berek! Gonisz!', 'Berek! Gonisz!', 0),
(15603, 'plPL', 'No proszę, witaj, Bessy. Dziś twoja kolej na spacer, prawda?', '', 0),
(15604, 'plPL', 'Biedna Bessy, zamknięta w stodole w taki upał. Przyniosę ci coś do przegryzienia!', '', 0),
(15605, 'plPL', 'Bessy jest dziś głodna, co? Pójdę ci przynieść jabłko.', '', 0),
(15606, 'plPL', 'Dzień dobry, Benjaminie! Mogę wziąć jabłko dla Bessy?', '', 0),
(15608, 'plPL', 'Witaj, Benjaminie! Nie masz nic przeciwko, żebym podkradł jabłko dla starej Bessy?', '', 0),
(15609, 'plPL', 'Benjaminie, stary przyjacielu, znajdziesz dziś jabłko dla Bessy?', '', 0),
(15610, 'plPL', '%s zrywa jabłko z drzewa.', '', 0),
(15611, 'plPL', 'Dzięki, Benjaminie!', '', 0),
(15612, 'plPL', 'Samuelu, ten stary wóz znowu ci się psuje?', '', 0),
(15613, 'plPL', 'Wóz znowu ci się zepsuł, Samuelu?', '', 0),
(15614, 'plPL', 'Taki stary wóz, nic dziwnego, że ci się zepsuł, Samuelu.', '', 0),
(15615, 'plPL', 'No cóż, przykro mi to słyszeć. Zajrzę później, jeśli będziesz potrzebował pomocy.', '', 0),
(15616, 'plPL', 'No, Bessy będzie zadowolona z tej przekąski.', '', 0),
(15617, 'plPL', 'Masz, Bessy, zjedz sobie jabłko, a ja cię przygotuję.', '', 0),
(15618, 'plPL', '%s karmi Bessy jaskrawoczerwonym jabłkiem.', '', 0),
(15619, 'plPL', 'No już, już, Siwko. Nie bądź zazdrosna, niedługo i ty wyruszysz na wielką przygodę.', '', 0),
(15620, 'plPL', 'Ho, ho, Siwko, dziś nie dostaniesz jabłek. Jutro zabierzemy cię do Południowego Brzegu, a stamtąd popłyniesz statkiem daleko za morze.', '', 0),
(15621, 'plPL', 'Och, Siwko, nie martw się, mój brat z Zachodniego Skraju dobrze się tobą zaopiekuje. Słyszałem, że ma piękną farmę i mnóstwo miejsca, żebyś mogła sobie pobiegać.', '', 0),
(15622, 'plPL', 'Młoda Siwka zazdrośnie tupie kopytem.', '', 0),
(15623, 'plPL', 'No dobra, Bessy, wyprowadzimy cię na spacer. Wio, wio!', '', 0),
(15624, 'plPL', 'Grzeczna dziewczynka, Bessy!', '', 0),
(15625, 'plPL', 'Jak tam, Samuelu?', '', 0),
(15626, 'plPL', 'Bessy radośnie rży.', '', 0),
(15627, 'plPL', 'Jasne, bierz śmiało, starczy dla wszystkich!', '', 0),
(15628, 'plPL', '%s mamrocze coś pod nosem przy pracy.', '', 0),
(15629, 'plPL', 'Ano, wciąż zepsuty. A na nowy mnie nie stać.', '', 0),
(15630, 'plPL', 'Nie, wciąż zepsuty. Chyba nie mam ani krzty szczęścia.', '', 0),
(15647, 'plPL', 'Wspaniała pogoda na ryby!', '', 0),
(15648, 'plPL', 'Nie można by sobie wymarzyć ładniejszego dnia!', '', 0),
(15649, 'plPL', 'Nie ma to jak wieczorne łowienie!', '', 0),
(15650, 'plPL', 'Oj tak! Nie ma to jak ciepłe powietrze i chłodny staw...', '', 0),
(15651, 'plPL', 'Szkoda tylko, że ryby biorą rzadziej niż komary gryzą...', '', 0),
(15652, 'plPL', 'Ano, gdyby tak każdy dzień był taki jak dziś...', '', 0),
(15653, 'plPL', 'Cicho bądź, tym gadaniem wypłoszysz ryby!', '', 0),
(15654, 'plPL', 'Phi, prawdziwi rybacy łowią i w największą ulewę!', '', 0),
(15655, 'plPL', 'Co mówiłeś?', '', 0),
(15656, 'plPL', 'Myślicie, że zobaczymy dziś starego Smolucha?', '', 0),
(15657, 'plPL', 'Założę się, że tym razem złowię coś dużego...', '', 0),
(15658, 'plPL', 'Oby tylko znowu nie wyciągnąć buta Reggy\'ego...', '', 0),
(15659, 'plPL', 'Może...', '', 0),
(15660, 'plPL', 'Wszystko może się zdarzyć...', '', 0),
(15661, 'plPL', 'Hehe, nie rób sobie zbyt wielkich nadziei...', '', 0),
(15662, 'plPL', 'Mam jedną!', '', 0),
(15663, 'plPL', 'Macie może trochę zapasowej przynęty?', '', 0),
(15664, 'plPL', 'Pamiętacie, jak złowiliśmy tego czerwonopłetwego murloka w Elwynn?', '', 0),
(15665, 'plPL', 'Dzięki Światłości, że nie ma tu Berthy...', '', 0),
(15666, 'plPL', 'Nie ma to jak ciepły dzień i żadnej starej, co by na człowieka wrzeszczała...', '', 0),
(15667, 'plPL', 'Nie ma to jak cisza i spokój... nie to co w domu!', '', 0),
(15668, 'plPL', 'Wiem coś o tym! Nie mam chwili spokoju, bo Sarah ciągle marudzi o obowiązkach!', '', 0),
(15669, 'plPL', 'Ano, i żadnego wrzeszczącego bachora, co by mącił spokój człowiekowi i jego rybie...', '', 0),
(15670, 'plPL', 'Tak mówisz teraz, ale przynajmniej czeka na ciebie ciepły obiad...', '', 0),
(15671, 'plPL', 'Mogło być gorzej, twoja żona mogła uciec do Wichrogrodu z jakimś handlarzem serów!', '', 0),
(15672, 'plPL', 'Lepiej nie mów tego zbyt głośno!', '', 0),
(15891, 'plPL', 'Co to ma znaczyć? STRAŻ!', '', 0),
(15892, 'plPL', 'Dość już od niego usłyszeliśmy.', '', 0),
(15893, 'plPL', 'Skoro mamy nowy plan, równie dobrze mogę wziąć jakąś broń i zbroję.', '', 0),
(15908, 'plPL', 'Nadjeżdża jeździec.', '', 0),
(15916, 'plPL', 'Dobrze. Smolny Młyn leży tuż na zachód stąd. A że czas nagli...', '', 0),
(15948, 'plPL', 'W drogę!', '', 0),
(15958, 'plPL', 'Zdawało mi się, że coś weszło do stodoły.', 'Zdawało mi się, że coś weszło do stodoły.', 0),
(15969, 'plPL', 'Coś spłoszyło tego konia. Idziemy!', 'Coś spłoszyło tego konia. Idziemy!', 0),
(15970, 'plPL', 'Thrall próbuje uspokoić konia.', '', 0),
(15974, 'plPL', 'Nie ma tu Tarethy. Ruszajmy do miasteczka.', '', 0),
(15975, 'plPL', 'Nie ma jej tutaj.', '', 0),
(15976, 'plPL', 'Thrall sam się zamknął w kaplicy. Teraz już nie ucieknie.', 'Thrall sam się zamknął w kaplicy. Teraz już nie ucieknie.', 0),
(15977, 'plPL', 'Taretha musi być w karczmie. Chodźmy.', '', 0),
(15978, 'plPL', 'Taretho! Cóż to za plugawa magia?', '', 0),
(15979, 'plPL', '', 'Thrallu, uciekłeś!', 0),
(15986, 'plPL', 'Jest tutaj, zatrzymajcie go!', 'Jest tutaj, zatrzymajcie go!', 0),
(15993, 'plPL', '', 'Tak, przyjaciele. Ten człowiek nie był czarodziejem z Dalaranu. Jego strój wyglądał zupełnie obco, a akcent był mi nieznany. Mamrotał tylko coś o czasie – czas to, czas tamto. Musicie znaleźć tego czarodzieja i przekonać go, żeby mnie uwolnił.', 0),
(15994, 'plPL', 'Wydostaniemy cię, Taretho. Nie martw się. Wątpię, by ten czarodziej odszedł daleko.', 'Wydostaniemy cię, Taretho. Nie martw się. Wątpię, by ten czarodziej odszedł daleko.', 0),
(16017, 'plPL', 'Kto to był... albo co to było?', '', 0),
(16082, 'plPL', '', 'Jestem wolna! Dziękuję wam wszystkim!', 0),
(16083, 'plPL', 'Cieszę się, że jesteś bezpieczna, Taretho. Nic z tego nie byłoby możliwe bez twoich przyjaciół. To oni do tego doprowadzili.', '', 0),
(16084, 'plPL', 'To kim są ci ludzie?', '', 0),
(16085, 'plPL', '', 'Thrallu, nigdy w życiu nie widziałam tych ludzi.', 0),
(16089, 'plPL', 'Żegnaj, Taretho. Nigdy nie zapomnę twojej dobroci.', '', 0),
(16090, 'plPL', '', 'Nazywają cię potworem. Ale to oni są potworami, nie ty. Żegnaj, Thrallu.', 0),
(16459, 'plPL', 'Jeśli chcesz, mogę cię zabrać prosto do Durnholdu.', '', 0),
(16460, 'plPL', 'Zanim zaniosę cię do Durnholdu, odbierz od Eroziona paczkę bomb zapalających. W końcu nie chcesz tracić czasu.', '', 0),
(16461, 'plPL', 'Jestem $ggotów:gotowa; lecieć do Twierdzy Durnhold.', 'Jestem $ggotów:gotowa; lecieć do Twierdzy Durnhold.', 0),
(16499, 'plPL', 'Thrall płoszy konia groźnym okrzykiem!', '', 0),
(17600, 'plPL', 'Zasłużyłem na wolność!', '', 0),
(17601, 'plPL', 'Ten dzień powinien był nadejść dawno temu! Z drogi!', '', 0),
(17602, 'plPL', 'Nie jestem już niewolnikiem!', '', 0),
(17603, 'plPL', 'Blackmoore ma wiele na sumieniu!', '', 0),
(17604, 'plPL', 'Zmusiliście mnie do tego!', '', 0),
(17605, 'plPL', 'Nie powinno było do tego dojść!', '', 0),
(17606, 'plPL', 'Nie prosiłem o to!', '', 0),
(17607, 'plPL', 'Mam wobec was ogromny dług, nieznajomi.', '', 0),
(17608, 'plPL', 'Dziękuję, nieznajomi. Daliście mi nadzieję.', '', 0),
(17609, 'plPL', 'Nie zmarnuję tej szansy. Odszukam swoje przeznaczenie.', '', 0),
(17610, 'plPL', 'Nie wygląda to dobrze...', '', 0),
(17611, 'plPL', 'Będę walczył... do końca!', '', 0),
(17612, 'plPL', 'Taretho...', '', 0),
(17613, 'plPL', 'Dobry dzień... by umrzeć.', '', 0),
(17622, 'plPL', 'Dobrze zatem. Ruszajmy!', '', 0),
(17623, 'plPL', 'Nigdy więcej nie dam się zakuć w kajdany!', '', 0),
(17753, 'plPL', 'Gdy będziesz $ggotów:gotowa; lecieć do Durnholdu, daj mi znać, a cię tam zaniosę.', '', 0),
(17966, 'plPL', 'Hal...', '', 0),
(17967, 'plPL', 'Tak, Nat?', '', 0),
(17968, 'plPL', 'Znowu miałem w nocy ten sen...', '', 0),
(17969, 'plPL', 'Który?', '', 0),
(17970, 'plPL', 'No ten sen... Ten zwariowany. Pamiętasz?', '', 0),
(17971, 'plPL', 'Smolny Młyn zostaje zniszczony przez jakąś szaloną armię nieumarłych i na zawsze staje się wrogiem Południowego Brzegu.', '', 0),
(17972, 'plPL', 'Wyobrażasz sobie coś takiego, Hal? Wyobrażasz?', '', 0),
(17973, 'plPL', 'Ten, w którym jestem w Durnholdzie, a ten jeden ork, którego Blackmoore trzyma jako swojego osobistego niewolnika, ucieka...', '', 0),
(17974, 'plPL', 'I w końcu niszczy całą twierdzę, uwalnia wszystkich orków, których trzymamy w obozach, i dochodzi do władzy jako król orków... Wódz czy jakoś tak.', '', 0),
(17975, 'plPL', 'Zwariowane, co?', '', 0),
(17976, 'plPL', 'No więc jestem na jakiejś górze z wielgachnym drzewem. Wszędzie biega pełno elfów...', '', 0),
(17977, 'plPL', 'Nagle znikąd przychodzi jakiś demon czy coś, wysoki na sto metrów, i zaczyna się wspinać na to drzewo...', '', 0),
(17978, 'plPL', 'A jakby tego było mało, tego wielkiego demona zabija gromada małych, unoszących się świetlików... Aha, w tym śnie byłem też elfką... No tak...', '', 0),
(17979, 'plPL', 'W tym śnie byłem mistrzem wędkarstwa całego świata. Przeprowadziłem się do jakiegoś miejsca zwanego Kalimdor...', '', 0),
(17980, 'plPL', 'I ludzie z całego świata przychodzą do mnie, żeby oddać mi hołd... i nauczyć się łowić ryby.', '', 0),
(17981, 'plPL', 'Jestem jak jakiś bóg wędkarstwa...', '', 0),
(17982, 'plPL', 'W ten to nawet ja nie mogę uwierzyć... Znasz tych dwóch wygadanych łobuzów, Forora i Tigule\'a?', '', 0),
(17983, 'plPL', 'No więc w tym śnie jakimś cudem wymyślają coś, co nazywa się lody, i dodają do nich truskawek... Krótko mówiąc, dorabiają się fortuny!', '', 0),
(17984, 'plPL', 'A jakby tego było mało, postanawiają rzucić interes z lodami i zostać poszukiwaczami przygód... Podróżują po całym świecie, aż w końcu znikają w jakimś portalu. Po tym śnie obudziłem się zlany zimnym potem...', '', 0),
(17985, 'plPL', 'Ten jest naprawdę ponury... No więc syn króla, Arthas... Wyrusza walczyć ze złem razem z Utherem... *Nat ociera pot z czoła*', '', 0),
(17986, 'plPL', 'Ale, o zgrozo, Arthasa pochłania zło i sam staje się zły...', '', 0),
(17987, 'plPL', 'No i wraca do króla, udaje miłego, dobywa miecza i przebija króla na wylot, aż po łokieć... no wiesz... zabija go na miejscu.', '', 0),
(17988, 'plPL', 'To się nigdy nie zdarzy, Nat.\n', '', 0),
(17989, 'plPL', 'Niemożliwe!\n', '', 0),
(17990, 'plPL', 'Czasem się o ciebie martwię, Nat.', '', 0),
(17991, 'plPL', 'Bez szans.\n', '', 0),
(17992, 'plPL', 'Nat, w życiu słyszałem już niejedną bujdę, ale ta bije wszystkie na głowę.\n', '', 0),
(17993, 'plPL', 'Co ty masz w tej fajce, Nat?\n', '', 0),
(17994, 'plPL', '*Hal kręci głową* Nat, Nat, Nat...\n', '', 0),
(17995, 'plPL', 'Zamknij się i łów, Nat.\n', '', 0),
(17996, 'plPL', 'Nienawidzę tego miejsca i wszystkich, którzy tu są! Smithers, zrób to! Smithers, zrób tamto! To co, teraz jestem rolnikiem, tak? Mam zbierać plony, tak? Mam nadzieję, że kiedyś całe to miejsce zamieni się w jeden wielki cmentarz, a wszystkie te gaduły zostaną pochowane właśnie tutaj, do licha!', '', 0),
(17997, 'plPL', '%s zbiera trochę warzyw.', '', 0),
(17998, 'plPL', '%s grzebie w ziemi.', '', 0),
(17999, 'plPL', '%s przesuwa kamień.', '', 0),
(18009, 'plPL', 'Czas, żeby stary Smithers zrobił sobie przerwę...', '', 0),
(18011, 'plPL', '%s ziewa.', '', 0),
(18012, 'plPL', 'No, z powrotem do harówki.', '', 0),
(18033, 'plPL', 'Ścisz głos, Helcularze. Wszędzie pełno obcych...', '', 0),
(18041, 'plPL', 'Więc możesz mnie nauczyć tej... tej...', '', 0),
(18042, 'plPL', 'Nekromancji. To się nazywa nekromancja. I tak, mam moc, by obdarzyć cię tym darem.', '', 0),
(18043, 'plPL', 'A Kirin Tor? Co Kirin Tor mówi o nekromancji?', '', 0),
(18044, 'plPL', 'To nie twoja sprawa, Helcularze, bo nie należysz ani do Kirin Toru, ani do nekromantów.', '', 0),
(18050, 'plPL', 'Ale mówiąc szczerze, guzik mnie obchodzi, co myśli Kirin Tor! To głupcy przywiązani do swoich przestarzałych zwyczajów.', '', 0),
(18051, 'plPL', 'Więc naucz mnie, Kel\'Thuzadzie. Naucz mnie wszystkiego, co wiesz...', '', 0),
(18052, 'plPL', 'W swoim czasie, Helcularze... Wszystko w swoim czasie...', '', 0),
(18060, 'plPL', 'Ten, w którym tysiące ludzi obserwują nas z nieba...', '', 0),
(18061, 'plPL', 'Jesteśmy jak ich kukiełki – tańczymy, płaczemy, walczymy i gadamy głupoty dla ich rozrywki.\n', '', 0),
(18062, 'plPL', 'Czasem nawet na jawie wydaje mi się, że nas obserwują. Może obserwują nas właśnie teraz...', '', 0),
(18064, 'plPL', 'Ahoj, Ed! Pokażę ci mój statek! *hik*', '', 0),
(18065, 'plPL', 'Prowadź, Sanders!', '', 0),
(18066, 'plPL', 'Co ty wyprawiasz, Sanders?', '', 0),
(18067, 'plPL', 'Sprawdzam tylko, czy nikt za nami nie lezie! *hik*', '', 0),
(18068, 'plPL', 'Czysto...', '', 0),
(18069, 'plPL', 'Oto i ona! Czyż nie jest piękna?', '', 0),
(18070, 'plPL', 'Ano, piękna, nie ma co. I zacumowałeś ją tuż obok mojej fregaty! *hik*', '', 0),
(18071, 'plPL', 'To monstrum jest twoje, Ed? Arrr... Ale kawał łajby!', '', 0),
(18072, 'plPL', 'Ano! Cała moja... Opłynę nią świat dookoła. Za morze!', '', 0),
(18073, 'plPL', 'Arrr, Ed! Ta to na pewno utrzyma się na wodzie!', '', 0),
(18074, 'plPL', 'Sanders, co masz w tej skrzyni?', '', 0),
(18075, 'plPL', 'Umiesz dochować tajemnicy, Ed? Arr, umarli nie opowiadają bajek!', '', 0),
(18077, 'plPL', 'To mój skarb, Ed. Dzieło mojego życia! Arrr... Jedna biała koszula godna samego króla piratów!', '', 0),
(18078, 'plPL', 'Jedna czerwona szarfa, którą możesz nosić na głowie albo na portkach. Duma floty, ta szarfa...', '', 0),
(18079, 'plPL', 'I na koniec, ale wcale nie najmniej ważna, jedna ogromna torba! Zmieści aż osiem całych jabłek! Osiem, Ed! Wierzysz!?', '', 0),
(18081, 'plPL', 'Jarrr! Ciszej, Ed! Wszędzie kręcą się szczury lądowe! Ich szczurze uszy tylko czyhają na takie westchnienia, jak to, co ci się właśnie wyrwało!', '', 0),
(18082, 'plPL', 'Wybacz, Sanders. Po prostu nigdy nie widziałem takich bogactw. Zaskoczyło mnie to.', '', 0),
(18083, 'plPL', 'Nic się nie stało, Ed. Mój łup jest dobrze zamknięty w tej skrzyni. Żaden głupiec nigdy nie dostanie skarbu kapitana Sandersa! Chodźmy się jeszcze napić. Trunki się kończą.', '', 0),
(18084, 'plPL', 'Ściszcie głosy. W pobliżu są obcy...', '', 0),
(18085, 'plPL', 'Bracia i siostry, zwołałem was tu dziś, by pomówić o losie Lordaeronu.', '', 0),
(18086, 'plPL', '%s ścisza głos do szeptu.', '', 0),
(18087, 'plPL', 'Słyszę różne rzeczy... Rzeczy, które nie powinny się dziać.', '', 0),
(18088, 'plPL', 'Umarli powstają... Nieumarli z mroźnych krain północy. Całe miasta przepadły bez śladu. Ja...', '', 0),
(18089, 'plPL', 'Słyszałem, że Północna Grań jest stracona...', '', 0),
(18090, 'plPL', 'W całej sali słychać westchnienia przerażenia.', '', 0),
(18091, 'plPL', 'Musimy być w gotowości. Walczyłem już z nieumarłymi. To bezlitosne maszyny do zabijania, pozbawione wszelkich uczuć i współczucia.', '', 0),
(18093, 'plPL', 'Tak, ja też z nimi walczyłem. Jako królestwo nie jesteśmy przygotowani, by odeprzeć taki atak.', '', 0),
(18094, 'plPL', 'Co proponujesz, Mograine?', '', 0),
(18095, 'plPL', 'Proponuję? Proponuję, żebyśmy się przygotowali. Żebyśmy przygotowali naszych bliskich, rodziny i przyjaciół na możliwość zagłady z rąk nieumarłych.', '', 0),
(18096, 'plPL', 'Jest jeszcze to...', '', 0),
(18097, 'plPL', '%s otwiera skrzynię.', '', 0),
(18098, 'plPL', '', 'Na Światłość! Co to jest?', 0),
(18099, 'plPL', 'Mam ten przedmiot od 10 lat. Od czasów Iglicy Czarnej Góry...', '', 0),
(18100, 'plPL', 'Wydarłem go ze szczątków orkowego porucznika – mrocznego czarownika... Pochodzi z ich ojczystego świata.', '', 0),
(18101, 'plPL', 'Nie podchodźcie zbyt blisko. Raz go dotknąłem... Tylko raz i nigdy więcej. Wspomnienia tamtego dnia wciąż mnie prześladują.', '', 0),
(18102, 'plPL', '%s zdejmuje rękawicę pancerną z prawej ręki i pokazuje wszystkim swoją okaleczoną dłoń.', '', 0),
(18103, 'plPL', 'Przypuszczam, że ten przedmiot to żywe ucieleśnienie cieni... ciemności... To manifestacja. To pustka.', '', 0),
(18104, 'plPL', 'Nie rozumiem, co ten zły artefakt ma wspólnego z nieumarłymi. Musimy go zniszczyć!', '', 0),
(18107, 'plPL', 'Nie, stary przyjacielu, ma z nimi bardzo wiele wspólnego.', '', 0),
(18108, 'plPL', 'Pozwólcie, że was zapytam, bracia i siostry: czy dobro może istnieć bez zła? Czy może być światło bez ciemności?', '', 0),
(18109, 'plPL', 'A jeśli odpowiedź brzmi „nie”, to czy nie jest możliwe, że skoro istnieje ten artefakt, musi istnieć także jego zupełne przeciwieństwo?', '', 0),
(18110, 'plPL', 'Wyobrażacie sobie, co materialne ucieleśnienie Światłości mogłoby zdziałać przeciwko nieumarłym?', '', 0),
(18112, 'plPL', 'Bzdura, Mograine! Trzeba go zniszczyć!', '', 0),
(18113, 'plPL', 'Zebranych ogarnia szok, a potem cisza.', '', 0),
(18117, 'plPL', 'Pochłonął Światłość!', '', 0),
(18121, 'plPL', 'Czy... czy on jaśnieje? Jego barwa... Zmienia się.', '', 0),
(18122, 'plPL', 'NA ŚWIATŁOŚĆ! Czy to możliwe? Czy to jest to?', '', 0),
(18123, 'plPL', 'Muszę wiedzieć... Dowiem się...', '', 0),
(18124, 'plPL', '%s wyciąga rękę, by dotknąć świetlistego kryształu.', '', 0),
(18125, 'plPL', 'Ja... To... To jest piękne. To, co poczułem, gdy go dotknąłem... Światłość przepłynęła przeze mnie, a ja przez nią... Uleczyła mojego ducha.', '', 0),
(18126, 'plPL', 'Twoja dłoń! Jest uleczona!', '', 0),
(18127, 'plPL', '%s odkłada kryształ z powrotem do skrzyni.', '', 0),
(18128, 'plPL', 'Nigdy więcej nie mówmy o tym dniu. Mamy wielu wrogów. Nie muszą wiedzieć, że posiadamy takie artefakty.', '', 0),
(18129, 'plPL', 'Widziałem to... Z tego błogosławionego kryształu wykujemy broń. Ta broń zawrze w sobie cząstkę każdego z nas... A gdy zostanie użyta przeciwko nieumarłym, powali ich. I pozostawi po sobie tylko popioły...', '', 0),
(18130, 'plPL', 'Spopielacz...', 'Spopielacz...', 0),
(18132, 'plPL', 'Kiedy już uruchomię tę kupę złomu, będę mógł chodzić po drogach i nie bać się, że napadną mnie bandyci!', '', 0),
(18133, 'plPL', 'Jeszcze tylko kilka uderzeń i będzie gotowe...', '', 0),
(18134, 'plPL', 'Może sprzedam te cudeńka innym goblinom? Będę bogaty! Bogaty, mówię!', '', 0),
(18135, 'plPL', 'Tak, imię Zixil będzie znał każdy dom! Zmonopolizuję rynek!', '', 0),
(18136, 'plPL', 'Łapy precz od płaszcza! Tak, tak, wiem, że też taki chcesz. Wszyscy chcą moich płaszczy. Wierz mi, osobo o niskim poziomie moralnym i społecznym, pewnego dnia zbiję fortunę na sprzedaży moich płaszczy. Wszyscy stąd aż po Żelazną Kuźnię poznają nazwisko Bartolo Ginsetti. Każdy będzie pożądał marki Ginsetti!', '', 0),
(18137, 'plPL', 'Hej, ty! Tak, ty, $gchłopcze:dziewczyno; z gminu. Chodź szybko, muszę ci coś powiedzieć... Muszę ci opowiedzieć o mojej wielkości, by nie przepadła w otchłani!', '', 0),
(18138, 'plPL', 'Ooooch, TAK! Podziwiajcie moje prężące się mięśnie. Napawajcie się blaskiem mojej sylwetki.', '', 0),
(18140, 'plPL', 'To szaleństwo! Mam dość! DOŚĆ!', '', 0),
(18141, 'plPL', 'WSZYSCY SŁUCHAĆ!', '', 0),
(18142, 'plPL', 'Do ciebie też mówię, panie Mograine w eleganckich portkach! ZAMKNIJ JADACZKĘ!', '', 0),
(18143, 'plPL', 'A TERAZ wszyscy w tym barze mają ograniczyć hałas do minimum, bo inaczej stary Jessen wyciągnie wałek i tasak i urządzi wam tu orkową jatkę! CZY WSZYSTKO JASNE?!!!', '', 0),
(18144, 'plPL', 'AAAAAAaaaaarrrrgh!!!!! CISZA!', '', 0),
(18157, 'plPL', '', 'Co podać?', 0),
(18158, 'plPL', '', 'Wrócę później.', 0),
(18159, 'plPL', '', 'Jeszcze grogu?', 0),
(18160, 'plPL', 'Spójrz na nią, Jon. Jest wspaniała!', '', 0),
(18161, 'plPL', 'W rzeczy samej. Czyż można lepiej upamiętnić więź przyjaźni i braterstwa między Smolnym Młynem a Południowym Brzegiem niż wznosząc tę wieżę w połowie drogi między oboma miasteczkami? Genialne!', '', 0),
(18201, 'plPL', 'Te przeklęte podatki łamią mi kręgosłup. Król Terenas chyba traci rozeznanie, jeśli myśli, że cała ta odbudowa ożywi gospodarkę.', 'Te przeklęte podatki łamią mi kręgosłup. Król Terenas chyba traci rozeznanie, jeśli myśli, że cała ta odbudowa ożywi gospodarkę.', 0),
(18202, 'plPL', 'Od czasu wojny nie jest sobą. Jakby z dnia na dzień postarzał się i zmienił w starca. Za to ten jego syn wyrośnie kiedyś na dobrego króla.\n', 'Od czasu wojny nie jest sobą. Jakby z dnia na dzień postarzał się i zmienił w starca. Za to ten jego syn wyrośnie kiedyś na dobrego króla.\n', 0),
(18203, 'plPL', 'Książę Arthas? Daj spokój. Z tego, co słyszałem, całe dnie ugania się za córką Proudmoore\'a. Ten chłopak ma w głowie co innego niż sprawy państwa, mówię ci.\n', 'Książę Arthas? Daj spokój. Z tego, co słyszałem, całe dnie ugania się za córką Proudmoore\'a. Ten chłopak ma w głowie co innego niż sprawy państwa, mówię ci.\n', 0),
(18204, 'plPL', 'Nie byłabym taka pewna. Słyszałam, że szkolą go na paladyna. Terenas ma nadzieję, że Srebrna Dłoń nauczy go trochę dyscypliny. Jeśli ktoś może sprowadzić Arthasa na właściwą drogę, to tylko stary Uther.', 'Nie byłabym taka pewna. Słyszałam, że szkolą go na paladyna. Terenas ma nadzieję, że Srebrna Dłoń nauczy go trochę dyscypliny. Jeśli ktoś może sprowadzić Arthasa na właściwą drogę, to tylko stary Uther.', 0),
(18205, 'plPL', 'Ano, to prawda. Uther – oto prawdziwy bohater ludu.', 'Ano, to prawda. Uther – oto prawdziwy bohater ludu.', 0),
(18206, 'plPL', 'Słyszałeś o nowym gladiatorze porucznika Blackmoore\'a? Podobno jest nie do pokonania.', 'Słyszałeś o nowym gladiatorze porucznika Blackmoore\'a? Podobno jest nie do pokonania.', 0),
(18207, 'plPL', 'Ano, widziałam, jak walczy. To ork – wielki jak mało który. Straciłam tygodniówkę, obstawiając przeciw niemu. Drugi raz tego błędu nie popełnię!', 'Ano, widziałam, jak walczy. To ork – wielki jak mało który. Straciłam tygodniówkę, obstawiając przeciw niemu. Drugi raz tego błędu nie popełnię!', 0),
(18208, 'plPL', 'Wygrana czy przegrana, porucznik musi być szalony, żeby trzymać takiego orka jak zwierzątko. Im nie można ufać. To zwierzęta.\n', 'Wygrana czy przegrana, porucznik musi być szalony, żeby trzymać takiego orka jak zwierzątko. Im nie można ufać. To zwierzęta.\n', 0),
(18209, 'plPL', 'Racja. Racja. Niech Światłość ma go w opiece, jeśli ten potwór kiedyś się uwolni!', 'Racja. Racja. Niech Światłość ma go w opiece, jeśli ten potwór kiedyś się uwolni!', 0),
(19171, 'plPL', 'Stać!', '', 0),
(19511, 'plPL', 'Stać!', 'Stać!', 0),
(19512, 'plPL', 'Natychmiast się poddaj!', 'Natychmiast się poddaj!', 0),
(19515, 'plPL', 'Ja tylko... wykonywałam rozkazy.', 'Ja tylko... wykonywałam rozkazy.', 0),
(19517, 'plPL', 'Blackmoore zażąda... twojej głowy!', 'Blackmoore zażąda... twojej głowy!', 0),
(19518, 'plPL', 'Przeklęta hołota!', 'Przeklęta hołota!', 0),
(19520, 'plPL', 'Nie czuję się... najlepiej.', '', 0),
(19521, 'plPL', 'Kiedy znowu dostaniemy jeść?', '', 0),
(19522, 'plPL', 'Pić... tak bardzo... pić.', '', 0),
(19555, 'plPL', '', 'Mogę się pobawić?', 0),
(19556, 'plPL', '', 'Fuj, chłopaki są obrzydliwi!', 0),
(19560, 'plPL', 'Słyszałam, że Blackmoore dziwnie się ostatnio zachowuje.', 'Słyszałam, że Blackmoore dziwnie się ostatnio zachowuje.', 0),
(19561, 'plPL', 'Myślę o urlopie. Słyszałam, że w Żagiewiu jest ładnie.', 'Myślę o urlopie. Słyszałam, że w Żagiewiu jest ładnie.', 0),
(19562, 'plPL', 'Oby już był fajrant.', 'Oby już był fajrant.', 0),
(27540, 'plPL', 'Nie... możliwe...', '', 0),
(50626, 'plPL', 'Który?', 'Który?', 0);
